func (s *Server) handleK8sFindings(w http.ResponseWriter, r *http.Request) {
	if !s.authorizeAdmin(r) {
		writeOpenAIError(w, http.StatusUnauthorized, "invalid admin token", "invalid_request_error", "invalid_api_key")
		return
	}
	if r.Method != http.MethodGet {
		writeOpenAIError(w, http.StatusMethodNotAllowed, "method not allowed", "invalid_request_error", "method_not_allowed")
		return
	}
	events := []store.K8sEvent{}
	revisions := []store.K8sResourceRevision{}
	truncated, eventsTruncated, revisionsTruncated := false, false, false
	eventsError, revisionsError := "", ""
	// The clusters whose turn was cut short. `truncated` and the per-window flags stay fleet-wide
	// "any of them" answers; this is the part that says where to look.
	clustersTruncated := []string{}
	for _, target := range targets {
		// Fetch only the kinds the two analyses below read, and ask for one row past the budget so
		// truncation is detectable rather than silent.
		part, err := s.db.ListK8sInventory(r.Context(), store.K8sInventoryFilter{
			ClusterID: target,
			Kinds:     kinds,
			Limit:     notifyScanBudget + 1,
		})
		if err != nil {
			writeOpenAIError(w, http.StatusInternalServerError, notifyScanTargetError(fanout, target, err), "server_error", "k8s_inventory_failed")
			return
		}
		inventoryFull := len(part) > notifyScanBudget
		if inventoryFull {
			part = part[:notifyScanBudget]
			truncated = true
		}
		items = append(items, part...)

	tz := s.flagValue(r.Context(), "k8s_notify_timezone")
	loc, tzNotice := notifyLocation(tz)
	clock := map[string]any{"timezone": loc.String()}
	if tzNotice != "" {
		clock["timezone_notice"] = tzNotice
	}
	if inQuietHours(quiet, now.In(loc).Hour()) {
		// Suppression says nothing was delivered; it must not also say nothing went wrong. The counters
		// and failures below are the ones the loop already produced, reported with the same keys and
		// the same wording the non-quiet path uses, so one fault does not read as two different ones
		// depending on the hour it happened to be noticed.
		out := map[string]any{"sent": 0, "suppressed": "quiet_hours", "quiet_hours": quiet, "truncated": truncated}
		for k, v := range clock {
			out[k] = v
		}
		for k, v := range window {
			out[k] = v
		}
		if truncated {
			out["truncation_notice"] = notifyScanTruncationNotice
		}
		writeJSON(w, http.StatusOK, out)
		return
	}

	rca := analyzer.AnalyzeRCA(items, events)
	rca = analyzer.EnrichWithConfigChanges(rca, revisions, now.UTC(), 24*time.Hour)
	sec := analyzer.AnalyzeSecurity(items)

	sent, undeliverable := 0, 0
	// A scan without cluster_id evaluates every cluster at once, so dedup, owner routing and the
	// deep link are keyed by the cluster each finding was made in — keyed by the request's
	// cluster_id, two clusters' workloads of the same name collapsed into one notification that
	// linked to no cluster. The request's cluster_id remains the fallback for a finding without one.
	notify := func(category, cluster, dedupKey, ns, kind, name, text string) {
		// Ask whether the message can be delivered before recording it as sent. Mattermost being
		// off, unconfigured or the category muted makes notifyMattermostTo a silent no-op, and
		// claiming the dedup window for it suppressed the finding for the next 6h — so a scan
		// scheduled before the webhook was configured produced no alert long after it worked.
		if !s.mattermostConfig(r.Context()).canNotify(category) {
			undeliverable++
			return
		}
		cluster = firstNonEmpty(cluster, clusterID)
		ok, derr := s.db.ShouldSendK8sNotification(r.Context(), cluster+"|"+dedupKey, now, 6*time.Hour)
		if derr != nil || !ok {
			return // NOTI-02 dedup
		}
		channel := ""
		if ns != "" {
			if owner, oerr := s.db.GetK8sNamespaceOwner(r.Context(), cluster, ns); oerr == nil {
				channel = resolveTeamChannel(teamChannels, owner.Team) // NOTI-04
			}
		}
		link := k8sDeepLink(requestBaseURL(r), cluster, ns, kind, name)
		s.notifyMattermostTo(r.Context(), category, channel, text+"\n"+link)
		sent++
	}

	for _, c := range rca {
		if c.Severity != "high" && c.Severity != "critical" {
			continue
		}
		notify("k8s_failure", c.ClusterID, "rca/"+c.Namespace+"/"+c.ResourceKind+"/"+c.ResourceName+"/"+c.Condition,
			c.Namespace, c.ResourceKind, c.ResourceName,
			"장애 후보["+c.Severity+"] "+c.Condition+" — "+c.Namespace+"/"+c.ResourceKind+"/"+c.ResourceName+"\n"+c.Cause)
	}
	for _, f := range sec.RBAC {
		if f.Severity != "critical" && f.Severity != "high" {
			continue
		}
		notify("k8s_security", f.ClusterID, "rbac/"+f.Namespace+"/"+f.ResourceName+"/"+f.Rule,
			f.Namespace, f.ResourceKind, f.ResourceName,
			"보안["+f.Severity+"] "+f.Rule+" — "+f.ResourceKind+"/"+f.ResourceName+"\n"+f.Message)
	}
	for _, p := range sec.PodSecurity {
		if p.Level != "privileged" {
			continue
		}
		notify("k8s_security", p.ClusterID, "podsec/"+p.Namespace+"/"+p.Name,
			p.Namespace, p.Kind, p.Name,
			"보안[high] Privileged 워크로드 — "+p.Namespace+"/"+p.Kind+"/"+p.Name+"\n"+strings.Join(p.Violations, ", "))
	}
	audit := map[string]any{"cluster_id": clusterID, "sent": sent, "undeliverable": undeliverable, "resources": len(items), "truncated": truncated}
	for k, v := range window {
		audit[k] = v
	}
	s.auditAdmin(r, "k8s.notify.scan", "", auditJSON(audit))
	// undeliverable counts findings left unsent because Mattermost is off, unconfigured or the
	// category is muted — they keep their dedup window and notify on the next scan once it works.
	out := map[string]any{
		"sent": sent, "undeliverable": undeliverable, "resources": len(items), "truncated": truncated,

	}
	return false
}

