	if err := json.Unmarshal(raw, &root); err != nil {
		return ScanNormalizeResult{}, err
	}
	s := strings.ToLower(strings.TrimSpace(scanner))
	requested := s
	if s == "" {
		s = detectScanner(root)
	}
	out := ScanNormalizeResult{
		Scanner:        s,
		ScannerVersion: defaults["scanner_version"],
		TargetType:     firstNonEmptyV(defaults["target_type"], strV(root["ArtifactType"])),
		TargetRef:      firstNonEmptyV(defaults["target_ref"], defaults["image"], strV(root["ArtifactName"])),
		ImageDigest:    defaults["image_digest"],
		Summary:        map[string]any{},
		Findings:       []VulnerabilityFinding{},
	}
	fallback := false
	switch s {
	case "grype":
		normalizeGrype(root, defaults, &out)
	case "trivy-operator", "vulnerabilityreport":
		out.Scanner = "trivy-operator"
		normalizeTrivyOperator(root, defaults, &out)
	case "trivy":
		out.Scanner = "trivy"
		normalizeTrivy(root, defaults, &out)
	default:
		// Whatever the artifact claimed to be, the reader that actually ran is Trivy's.
		// Recording the requested (or undetected) label here stored rows as
		// scanner="unknown"/"snyk" while every field in them came out of the Trivy
		// reader — the scan list, the audit entry and the DW export then named a
		// parser that never ran.
		out.Scanner = "trivy"
