			LEFT JOIN k8s_cluster_groups g ON g.id = c.group_id
			LEFT JOIN k8s_namespace_ownership o ON o.cluster_id = i.cluster_id AND o.namespace = i.namespace`
	}
	query += ` WHERE 1=1`
	if f.ClusterID != "" {
		query += ` AND i.cluster_id = ?`
		args = append(args, f.ClusterID)
